INSERT INTO `space_versions` (`version`, `title`, `summary`, `created_at`) VALUES ('v137', '取消豆包图片公开图床中转', '网页版豆包无法访问外部链接，原先「把图片先传到公开图床、再把链接发给豆包让它打开看图」的中转设定已整个取消：图片不再上传到任何外部图床，豆包的发送也不再附带公开链接、不再为此强制开启联网搜索。现在给豆包发图片会和其它没有图片通道的网页智能体一样如实提示这次没有收到图片（图片仍保存在聊天里，文字消息不受影响）；要让智能体看图，可发到 Muse、API 智能体，以及 DeepSeek / ChatGPT / Claude / Gemini / Mistral 网页版的房间。豆包的文字对话、令牌直连等其它功能不变。', strftime('%s','now') * 1000);
